export function getEditorialSkillsAdapterJs() {
  return "// Skill normalization utilities for EditorialTemplate\nconst TRIVIAL_SKILL_PATTERNS = [\n  /^dom\\s*manipulation$/i,\n  /^async[\\s/]*await$/i,\n  /^css\\s*flexbox$/i,\n  /^css\\s*grid$/i,\n  /^flexbox$/i,\n  /^grid\\s*layout$/i,\n  /^responsive\\s*(web\\s*)?design$/i,\n  /^cross[- ]browser/i,\n  /^semantic\\s*html$/i,\n  /^rest(ful)?\\s*api(\\s*development|\\s*integration)?$/i,\n  /^api\\s*integration$/i,\n  /^state\\s*management$/i,\n  /^json$/i,\n  /^ajax$/i,\n  /^debugging$/i,\n  /^clean\\s*code$/i,\n  /^code\\s*review$/i,\n  /^problem\\s*solving$/i,\n];\n\nfunction cleanSkillName(raw) {\n  const trimmed = String(raw || \"\").trim();\n  if (/^javascript\\s*(\\(es6\\+\\)|\\(es6\\))?$/i.test(trimmed) || /^js$/i.test(trimmed)) return \"JavaScript\";\n  if (/^typescript$/i.test(trimmed) || /^ts$/i.test(trimmed)) return \"TypeScript\";\n  if (/^react(\\.js|js)?$/i.test(trimmed)) return \"React\";\n  if (/^next(\\.js|js)?$/i.test(trimmed)) return \"Next.js\";\n  if (/^node(\\.js|js)?$/i.test(trimmed)) return \"Node.js\";\n  if (/^express(\\.js|js)?$/i.test(trimmed)) return \"Express.js\";\n  if (/^html5?$/i.test(trimmed)) return \"HTML5\";\n  if (/^css3?$/i.test(trimmed)) return \"CSS3\";\n  if (/^tailwind(\\s*css)?$/i.test(trimmed)) return \"Tailwind CSS\";\n  if (/^mongo(\\s*db)?$/i.test(trimmed)) return \"MongoDB\";\n  if (/^postgres(ql)?$/i.test(trimmed)) return \"PostgreSQL\";\n  return trimmed;\n}\n\nfunction isTrivialSkill(name) {\n  return TRIVIAL_SKILL_PATTERNS.some((pat) => pat.test(String(name || \"\").trim()));\n}\n\nexport function normalizeSkills(rawSkills) {\n  if (!rawSkills) return [];\n  const rawList = [];\n\n  if (Array.isArray(rawSkills)) {\n    for (const item of rawSkills) {\n      if (typeof item === \"string\") {\n        const trimmed = item.trim();\n        if (trimmed) rawList.push({ name: trimmed, category: \"Core Technologies\", level: \"intermediate\" });\n      } else if (typeof item === \"object\" && item !== null) {\n        if (item.name && String(item.name).trim()) {\n          const level = [\"beginner\", \"intermediate\", \"advanced\", \"expert\"].includes(item.level || \"\")\n            ? item.level\n            : \"intermediate\";\n          rawList.push({\n            name: String(item.name).trim(),\n            category: (item.category && String(item.category).trim()) || \"Core Technologies\",\n            level,\n          });\n        }\n      }\n    }\n  } else if (typeof rawSkills === \"object\" && rawSkills !== null) {\n    for (const [category, skills] of Object.entries(rawSkills)) {\n      if (Array.isArray(skills)) {\n        for (const name of skills) {\n          if (typeof name === \"string\" && name.trim()) {\n            rawList.push({ name: name.trim(), category: category.trim() || \"Core Technologies\", level: \"intermediate\" });\n          }\n        }\n      } else if (typeof skills === \"string\" && skills.trim()) {\n        const split = skills.split(/[,•|]+/).map((s) => s.trim()).filter(Boolean);\n        for (const name of split) {\n          rawList.push({ name, category: category.trim() || \"Core Technologies\", level: \"intermediate\" });\n        }\n      }\n    }\n  }\n\n  if (rawList.length === 0) return [];\n  const seen = new Set();\n  const filteredList = [];\n\n  for (const sk of rawList) {\n    const cleaned = cleanSkillName(sk.name);\n    const key = cleaned.toLowerCase().replace(/[^a-z0-9]/g, \"\");\n    if (!key || seen.has(key)) continue;\n    if (rawList.length > 5 && isTrivialSkill(sk.name)) continue;\n    seen.add(key);\n    filteredList.push({ ...sk, name: cleaned });\n  }\n\n  return filteredList.length > 0 ? filteredList : rawList;\n}\n";
}
